INSERT INTO public.medicine_classifications (medicine_id, class_id, is_primary)
SELECT m.id, c.id, true FROM (VALUES
('paracetamol','non-opioid-analgesics'),('ibuprofen','nsaids'),('diclofenac','nsaids'),('naproxen','nsaids'),
('amoxicillin','beta-lactams'),('amoxicillin-clavulanic-acid','beta-lactams'),('cefixime','beta-lactams'),('ceftriaxone','beta-lactams'),
('azithromycin','macrolides'),('doxycycline','tetracyclines'),('metronidazole','nitroimidazoles'),
('omeprazole','ppis'),('pantoprazole','ppis'),('ondansetron','antiemetics'),
('cetirizine','antihistamines'),('loratadine','antihistamines'),('salbutamol','bronchodilators'),
('metformin','biguanides'),('glimepiride','sulfonylureas'),
('amlodipine','ccb'),('losartan','arbs'),('telmisartan','arbs'),('furosemide','loop-diuretics'),
('atorvastatin','statins'),('rosuvastatin','statins'),
('aspirin','antiplatelets'),('clopidogrel','antiplatelets'),('levothyroxine','thyroid-hormones')
) AS v(med,cls)
JOIN public.medicines m ON m.slug = v.med
JOIN public.drug_classes c ON c.slug = v.cls;

