('Asthalin','salbutamol','Cipla','Salbutamol','100 mcg/puff','Inhaler'),
('Glycomet','metformin','USV','Metformin hydrochloride','500 mg','Tablet'),
('Amaryl','glimepiride','Sanofi India','Glimepiride','2 mg','Tablet'),
('Amlong','amlodipine','Micro Labs','Amlodipine','5 mg','Tablet'),
('Losar','losartan','Unichem Laboratories','Losartan potassium','50 mg','Tablet'),
('Telma','telmisartan','Glenmark Pharmaceuticals','Telmisartan','40 mg','Tablet'),
('Atorva','atorvastatin','Zydus Lifesciences','Atorvastatin','10 mg','Tablet'),
('Rosuvas','rosuvastatin','Sun Pharmaceutical Industries','Rosuvastatin','10 mg','Tablet'),
('Thyronorm','levothyroxine','Abbott India','Levothyroxine sodium','50 mcg','Tablet'),
('Lasix','furosemide','Sanofi India','Furosemide','40 mg','Tablet'),
('Ecosprin','aspirin','USV','Aspirin','75 mg','Tablet'),
('Clopilet','clopidogrel','Sun Pharmaceutical Industries','Clopidogrel','75 mg','Tablet')
) AS v(brand,med,maker,comp,strength,form)
JOIN public.medicines m ON m.slug = v.med
LEFT JOIN public.manufacturers mf ON mf.name = v.maker;

INSERT INTO public.manufacturers (name) VALUES ('Micro Labs'),('Novartis India'),('Alembic Pharmaceuticals'),('Sanofi India'),('Unichem Laboratories'),('Glenmark Pharmaceuticals') ON CONFLICT DO NOTHING;
UPDATE public.brands b SET manufacturer_id = mf.id FROM public.manufacturers mf
WHERE b.manufacturer_id IS NULL AND mf.name = CASE b.brand_name
  WHEN 'Dolo 650' THEN 'Micro Labs' WHEN 'Amlong' THEN 'Micro Labs' WHEN 'Voveran' THEN 'Novartis India'
  WHEN 'Azithral' THEN 'Alembic Pharmaceuticals' WHEN 'Amaryl' THEN 'Sanofi India' WHEN 'Lasix' THEN 'Sanofi India'
  WHEN 'Losar' THEN 'Unichem Laboratories' WHEN 'Telma' THEN 'Glenmark Pharmaceuticals' END;

INSERT INTO public.medicine_references (medicine_id, reference_id)
SELECT m.id, r.id FROM public.medicines m CROSS JOIN public.references r
WHERE r.source_name IN ('National List of Essential Medicines (NLEM), India','KD Tripathi, Essentials of Medical Pharmacology','British National Formulary (BNF)');

INSERT INTO public.drug_interactions (medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration)
SELECT a.id, b.id, v.sev, v.descr, v.mech, v.sig, v.cons FROM (VALUES
('aspirin','ibuprofen','moderate','Ibuprofen can reduce the cardioprotective antiplatelet effect of low-dose aspirin.','Competition for the COX-1 acetylation site on platelets.','May reduce cardiovascular protection when used regularly together.','Where both are needed, timing separation or an alternative analgesic is often considered.'),
('clopidogrel','omeprazole','major','Omeprazole reduces conversion of clopidogrel to its active metabolite.','CYP2C19 inhibition by omeprazole.','Reduced antiplatelet effect with possible increased thrombotic risk.','Pantoprazole is commonly preferred when a PPI is required with clopidogrel.'),
('metformin','furosemide','moderate','Diuretic-induced dehydration can precipitate metformin accumulation.','Reduced renal clearance of metformin during volume depletion.','Increased risk of lactic acidosis in dehydration or acute illness.','Renal function monitoring and sick-day guidance are standard practice.'),
('losartan','ibuprofen','moderate','NSAIDs can reduce the antihypertensive effect of ARBs and impair renal function.','Prostaglandin inhibition reduces renal perfusion and sodium excretion.','Blood pressure rise and risk of acute kidney injury, especially with a diuretic.','Renal function and blood pressure monitoring are advised.'),
('levothyroxine','omeprazole','moderate','Reduced gastric acidity can decrease levothyroxine absorption.','Higher gastric pH reduces dissolution and absorption.','Possible rise in TSH and reduced control of hypothyroidism.','TSH monitoring after starting or stopping the PPI is advised.'),
('atorvastatin','azithromycin','moderate','Macrolides may increase statin exposure and myopathy risk.','Inhibition of CYP3A4 and transporter-mediated clearance.','Increased risk of muscle symptoms and rarely rhabdomyolysis.','Muscle symptom review during concurrent therapy is advised.'),
('aspirin','clopidogrel','moderate','Combined antiplatelet therapy increases bleeding risk.','Additive inhibition of platelet function by two different pathways.','Higher bleeding risk; the combination is nonetheless indicated in specific cardiac situations.','Duration of dual therapy is determined by the treating specialist.'),
('metronidazole','warfarin-placeholder','moderate','placeholder','placeholder','placeholder','placeholder')
) AS v(a,b,sev,descr,mech,sig,cons)
JOIN public.medicines a ON a.slug = v.a
JOIN public.medicines b ON b.slug = v.b;

INSERT INTO public.flashcards (question, answer, topic, difficulty, medicine_id)
SELECT v.q, v.a, v.t, v.d, m.id FROM (VALUES
('Which class does losartan belong to?','ARB — Angiotensin II receptor blocker','Drug Classes','easy','losartan'),
('What is the antidote for paracetamol overdose?','N-acetylcysteine','Emergency','easy','paracetamol'),
('What is the main mechanism of omeprazole?','Irreversible inhibition of the gastric H+/K+-ATPase (proton pump)','Mechanism','easy','omeprazole'),
('How is metformin eliminated?','Excreted unchanged by the kidneys; it is not metabolised','ADME','medium','metformin'),
('Why is doxycycline avoided in pregnancy and young children?','Risk of tooth discolouration and effects on developing bone','Safety','easy','doxycycline'),
('How long does the antiplatelet effect of aspirin last?','7-10 days, the lifespan of the platelet, because COX-1 inhibition is irreversible','Pharmacodynamics','medium','aspirin'),
('Which enzyme activates clopidogrel?','CYP2C19 in the liver','ADME','medium','clopidogrel'),
('What is the classic dose-related adverse effect of amlodipine?','Ankle oedema','Adverse Effects','easy','amlodipine'),
('When should levothyroxine be taken?','On an empty stomach, 30-60 minutes before breakfast','Counselling','easy','levothyroxine'),
('Which electrolyte must be monitored with furosemide?','Potassium (hypokalaemia risk)','Monitoring','easy','furosemide'),
('What must be strictly avoided with metronidazole?','Alcohol, due to a disulfiram-like reaction','Safety','easy','metronidazole'),
('Which ARB has the longest half-life?','Telmisartan, about 24 hours','Pharmacokinetics','medium','telmisartan'),
('What is the mechanism of salbutamol?','Beta-2 adrenoceptor agonism relaxing bronchial smooth muscle','Mechanism','easy','salbutamol'),
('Why is ondansetron used cautiously in cardiac patients?','It can prolong the QT interval','Safety','medium','ondansetron'),
('What does clavulanic acid add to amoxicillin?','Beta-lactamase inhibition, protecting amoxicillin from breakdown','Mechanism','easy','amoxicillin-clavulanic-acid')
) AS v(q,a,t,d,med)
JOIN public.medicines m ON m.slug = v.med;

INSERT INTO public.flashcards (question, answer, topic, difficulty) VALUES
('What does ADME stand for?','Absorption, Distribution, Metabolism, Excretion','ADME','easy'),
('Define bioavailability.','The fraction of an administered dose that reaches the systemic circulation unchanged','Pharmacokinetics','easy'),
('Define half-life.','The time taken for the plasma concentration of a drug to fall by half','Pharmacokinetics','easy'),
('What does the suffix -prazole indicate?','Proton pump inhibitor','Suffixes','easy'),
('What does the suffix -pril indicate?','ACE inhibitor','Suffixes','easy'),
('Pharmacokinetics vs pharmacodynamics?','Pharmacokinetics is what the body does to the drug; pharmacodynamics is what the drug does to the body','Concepts','easy');

INSERT INTO public.quiz_questions (question, question_type, options, correct_answer, explanation, topic, difficulty) VALUES
('Losartan belongs to which drug class?','mcq',ARRAY['ACE inhibitor','ARB','Beta blocker','Calcium channel blocker'],'ARB','Losartan blocks the angiotensin II AT1 receptor. The -sartan suffix is a memory aid for ARBs.','Drug Classes','easy'),
('Which medicine is the usual first-line oral therapy in type 2 diabetes?','mcq',ARRAY['Glimepiride','Metformin','Insulin glargine','Amlodipine'],'Metformin','Metformin is weight neutral, does not intrinsically cause hypoglycaemia and has strong long-term evidence.','Pharmacology','easy'),
('The antidote for paracetamol overdose is:','mcq',ARRAY['Naloxone','Flumazenil','N-acetylcysteine','Atropine'],'N-acetylcysteine','N-acetylcysteine replenishes glutathione, which detoxifies the reactive metabolite NAPQI.','Emergency','easy'),
('Which suffix usually indicates a proton pump inhibitor?','mcq',ARRAY['-sartan','-prazole','-olol','-statin'],'-prazole','Omeprazole, pantoprazole and rabeprazole are proton pump inhibitors.','Medical Terms','easy'),
('Metformin is mainly eliminated by:','mcq',ARRAY['Hepatic metabolism','Renal excretion unchanged','Biliary excretion after conjugation','Exhalation'],'Renal excretion unchanged','Metformin is not metabolised; renal impairment therefore raises the risk of accumulation.','ADME','medium'),
('Which adverse effect is characteristic of amlodipine?','mcq',ARRAY['Dry cough','Ankle oedema','Hyperkalaemia','Bradycardia'],'Ankle oedema','Dihydropyridine calcium channel blockers cause dose-related peripheral oedema.','Pharmacology','easy'),
('Doxycycline should generally be avoided in:','mcq',ARRAY['Adults with pneumonia','Pregnancy','Acne','Rickettsial infection'],'Pregnancy','Tetracyclines affect developing teeth and bone.','Pharmacology','easy'),
('Aspirin''s antiplatelet effect lasts about:','mcq',ARRAY['4 hours','24 hours','7-10 days','30 days'],'7-10 days','COX-1 inhibition in platelets is irreversible, so the effect lasts the platelet lifespan.','Pharmacodynamics','medium'),
('Which PPI is usually preferred alongside clopidogrel?','mcq',ARRAY['Omeprazole','Esomeprazole','Pantoprazole','Lansoprazole'],'Pantoprazole','Pantoprazole has less CYP2C19 inhibition, so it interferes less with clopidogrel activation.','Interactions','hard'),
('Bioavailability refers to:','mcq',ARRAY['How fast a drug is excreted','The fraction of the dose reaching systemic circulation unchanged','The volume the drug distributes into','The strength of receptor binding'],'The fraction of the dose reaching systemic circulation unchanged','It is a key absorption parameter within ADME.','ADME','easy'),
('Metronidazole must not be taken with:','mcq',ARRAY['Milk','Alcohol','Vitamin C','Paracetamol'],'Alcohol','A disulfiram-like reaction can occur with flushing, nausea and vomiting.','Safety','easy'),
('Pharmacodynamics is best described as:','mcq',ARRAY['What the body does to the drug','What the drug does to the body','How a drug is manufactured','How a drug is stored'],'What the drug does to the body','Pharmacokinetics is the reverse: what the body does to the drug.','Concepts','easy'),
('Salbutamol acts on which receptor?','mcq',ARRAY['Beta-1','Beta-2','Alpha-1','Muscarinic'],'Beta-2','Beta-2 agonism relaxes bronchial smooth muscle.','Mechanism','easy'),
('Levothyroxine is best taken:','mcq',ARRAY['With breakfast','On an empty stomach before breakfast','With calcium tablets','At bedtime with milk'],'On an empty stomach before breakfast','Food, calcium and iron reduce absorption.','Counselling','easy'),
('Which class does azithromycin belong to?','mcq',ARRAY['Beta-lactam','Macrolide','Tetracycline','Fluoroquinolone'],'Macrolide','Azithromycin binds the 50S ribosomal subunit.','Drug Classes','easy'),
('Furosemide acts on which part of the nephron?','mcq',ARRAY['Proximal tubule','Thick ascending limb of the loop of Henle','Distal convoluted tubule','Collecting duct'],'Thick ascending limb of the loop of Henle','It inhibits the Na-K-2Cl co-transporter there.','Pharmacology','medium'),
('Statins inhibit which enzyme?','mcq',ARRAY['HMG-CoA reductase','Cyclo-oxygenase','ACE','Xanthine oxidase'],'HMG-CoA reductase','This is the rate-limiting step of hepatic cholesterol synthesis.','Mechanism','easy'),
('Ondansetron blocks which receptor?','mcq',ARRAY['Dopamine D2','Histamine H1','Serotonin 5-HT3','Muscarinic M1'],'Serotonin 5-HT3','It acts on vagal afferents and the chemoreceptor trigger zone.','Mechanism','medium'),
('ACE inhibitors commonly cause which distinctive adverse effect?','mcq',ARRAY['Ankle oedema','Dry cough','Hair loss','Tinnitus'],'Dry cough','Bradykinin accumulation is the usual explanation; ARBs avoid this.','Pharmacology','easy'),
('Which statement about drug-name suffixes is correct?','true_false',ARRAY['True','False'],'False','Suffixes are memory aids only; exceptions exist and the actual record must always be checked. (Statement: suffixes are absolute classification rules.)','Medical Terms','easy');

INSERT INTO public.mnemonics (title, content, explanation, class_id)
SELECT v.t, v.c, v.e, dc.id FROM (VALUES
('ARBs end in -sartan','Losartan, Valsartan, Telmisartan, Candesartan, Olmesartan','All block the angiotensin II AT1 receptor.','arbs'),
('PPIs end in -prazole','Omeprazole, Pantoprazole, Rabeprazole, Esomeprazole','All irreversibly block the gastric proton pump.','ppis'),
('Statins end in -statin','Atorvastatin, Rosuvastatin, Simvastatin','All inhibit HMG-CoA reductase.','statins'),
('CCBs end in -dipine','Amlodipine, Nifedipine, Felodipine','Dihydropyridine calcium channel blockers; ankle oedema is the clue.','ccb')
) AS v(t,c,e,cls)
JOIN public.drug_classes dc ON dc.slug = v.cls;
